window.VeilGardeData.files["Tests-VeilGardeInferenceTests"] = {"group":"Tests-VeilGardeInferenceTests","files":[{"path":"Tests/VeilGardeInferenceTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,31]],"header":{"lines":[1,8],"target":"VeilGardeInferenceTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1391,"scopes":[["E","Fixture",null,"",13,13,[13,13],31,null,-1,0,"a",[]],["f","crop",["_"],"static",20,20,[20,44],20,null,0,8,"a"],["v","weightsPresent",null,"static",27,27,[27,36],30,null,0,0,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Inference tests read by repo path: the two parity crops and VeilGarde's own route\n//        goldens for them, and whether the DINOv2 weights are present.\n//\n\nimport Foundation\nimport VeilGardeInference\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static func crop(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeInferenceTests/Fixtures/crops/\\(name)\") }\n\n    /// The parity fixtures too large for the repo (dino_parity.safetensors is 1.8 MB), in the work\n    /// area's parity/; VEILGARDE_PARITY_DIR names another folder.\n    static let parityDir = URL(fileURLWithPath: ProcessInfo.processInfo.environment[\"VEILGARDE_PARITY_DIR\"]\n        ?? WorkArea.resolve()?.parity.path ?? \"parity\")\n\n    static var weightsPresent: Bool {\n        ShippedBundle.registerWeightFolders()\n        return WeightLocator.shared.url(.dinov2Small) != nil\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeInferenceTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1394,"scopes":[["S","InferenceLinkTests",null,"",12,13,[13,26],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilGardeInference\n\n@Suite(\"Inference links\")\nstruct InferenceLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeInferenceTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1396,"scopes":[["S","InferenceMLXSuites",null,"",20,21,[21,26],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under InferenceMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Inference: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct InferenceMLXSuites {}\n"},{"path":"Tests/VeilGardeInferenceTests/RouteGoldenTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,133]],"header":{"lines":[1,13],"target":"VeilGardeInferenceTests","what":[6,12],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1397,"scopes":[["f","leaves",["_","_"],"",20,20,[20,66],24,[19,19],-1,0,"a"],["f","compare",["_","_","tolerance"],"",28,28,[28,102],44,[26,27],-1,0,"a"],["X","InferenceMLXSuites",null,"",46,46,[46,29],133,null,-1,0,"a"],["S","RouteGoldenTests",null,"",47,48,[48,28],132,null,2,0,"a"],["f","routeJSON",["name"],"",52,53,[53,44],65,null,3,0,"a"],["f","schemaV1",[],"",67,68,[68,31],75,null,3,0,"a"],["f","semanticRemoved",[],"",77,78,[78,38],85,null,3,0,"a"],["f","customPipeline",[],"",87,88,[88,37],115,null,3,0,"a"],["f","dinoParity",[],"",119,119,[119,33],131,null,3,0,"a"]],"old":"","new":"//\n//  RouteGoldenTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The full detector against VeilGarde's own goldens (`veilgarde route --json` on the two\n//        parity crops with the shipped bundle): every label and structural field equal, every\n//        number within 1e-4 (DINOv2's matrix kernels move with Frigate's MLX revision by about\n//        1e-5). The goldens were re-recorded in schema v1 on 2026-10-21 after the stack's numbers\n//        were checked equal to the schema-v3 goldens', and the verdicts stay pinned here by value.\n//        The members and revisions in order; the schema-v1 keys; the semantic tiles removed;\n//        DINOv2 against the HF reference embeddings.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n/// Every leaf of a JSON value with its path.\nfunc leaves(_ value: Any, _ path: String = \"\") -> [(String, Any)] {\n    if let d = value as? [String: Any] { return d.keys.sorted().flatMap { leaves(d[$0]!, path.isEmpty ? $0 : \"\\(path).\\($0)\") } }\n    if let a = value as? [Any] { return a.enumerated().flatMap { leaves($1, \"\\(path)[\\($0)]\") } }\n    return [(path, value)]\n}\n\n/// Labels exact, numbers within `tolerance`, times_sec aside; returns the worst numeric difference and\n/// any mismatches.\nfunc compare(_ a: Data, _ b: Data, tolerance: Double) throws -> (worst: Double, mismatches: [String]) {\n    let kept: ((String, Any)) -> Bool = { !$0.0.hasPrefix(\"times_sec\") }\n    let x = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: a)).filter(kept))\n    let y = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: b)).filter(kept))\n    var worst = 0.0\n    var mismatches = Array(Set(x.keys).symmetricDifference(y.keys)).sorted()\n    for key in Set(x.keys).intersection(y.keys) {\n        if let m = x[key] as? NSNumber, let n = y[key] as? NSNumber, CFGetTypeID(m) != CFBooleanGetTypeID() {\n            let d = abs(m.doubleValue - n.doubleValue)\n            worst = max(worst, d)\n            if d > tolerance { mismatches.append(\"\\(key): \\(m) vs \\(n)\") }\n        } else if \"\\(x[key]!)\" != \"\\(y[key]!)\" {\n            mismatches.append(\"\\(key): \\(x[key]!) vs \\(y[key]!)\")\n        }\n    }\n    return (worst, mismatches)\n}\n\nextension InferenceMLXSuites {\n    @Suite(\"Full detector goldens\", .serialized, .enabled(if: Fixture.weightsPresent))\n    struct RouteGoldenTests {\n        /// The verdicts of 2026-10-21, as the schema-v3 goldens held them before the stack was a list.\n        static let verdicts: [String: (p: Float, prediction: String)] = [\"crop_ben\": (0.1059354618191719, \"real\"), \"crop_fox\": (0.018225347623229027, \"real\")]\n\n        @Test(\"the result matches the golden: labels exact, numbers within 1e-4\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func routeJSON(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"\\(name).png\"))\n            let result = try Detector.detect(cgImage: cg, config: InferenceConfig())\n            let ours = try ResultJSON.encode(result, times: [], device: \"route\")\n            let (worst, mismatches) = try compare(ours, Data(contentsOf: Fixture.crop(\"\\(name).route.json\")), tolerance: 1e-4)\n            #expect(mismatches.isEmpty, \"\\(mismatches.prefix(5))\")\n            #expect(worst < 1e-4, \"max |Δ| \\(worst)\")\n            let pinned = try #require(Self.verdicts[name])\n            #expect(abs(result.p - pinned.p) < 1e-4 && result.prediction == pinned.prediction)\n            #expect(result.stack.map(\\.name) == [\"screenshot\", \"camera\", \"capture\", \"art\", \"blur\", \"human\", \"preview\", \"semantic-tiles\"])\n            #expect(result.revisions.map(\\.name) == [\"combiner\", \"frame-seam\", \"preview-tail\"])\n            #expect(result.revisions.revision(\"combiner\")?.text(\"anchor\") == \"camera\")\n        }\n\n        @Test(\"the result JSON is schema v1\")\n        func schemaV1() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_fox.png\"))\n            let result = try Detector.detect(cgImage: cg, config: InferenceConfig())\n            let json = try #require(JSONSerialization.jsonObject(with: ResultJSON.encode(result, times: [], device: \"route\")) as? [String: Any])\n            #expect(Set(json.keys) == [\"bundle\", \"device\", \"image\", \"revisions\", \"schema_version\", \"stack\", \"times_sec\", \"verdict\"])\n            #expect(json[\"schema_version\"] as? Int == 1)\n            #expect(result.imageWidth == cg.width && result.imageHeight == cg.height)\n        }\n\n        @Test(\"removing the semantic tiles runs no token head and the preview tail never arms\")\n        func semanticRemoved() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_fox.png\"))\n            var config = InferenceConfig()\n            config.semanticResponsibility = .semanticRemoved\n            let r = try Detector.detect(cgImage: cg, config: config)\n            #expect(r.stack.member(\"semantic-tiles\") == nil)\n            #expect(r.revisions.revision(\"preview-tail\")?.applied == false && r.revisions.revision(\"preview-tail\")?.flag(\"triggered\") == false)\n        }\n\n        @Test(\"a pipeline declared in place runs only its members and revisions\")\n        func customPipeline() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_ben.png\"))\n            let pipeline = Pipeline {\n                Stack {\n                    Screenshot()\n                    Camera()\n                    Capture()\n                    for kind in HeadKind.combinerOrder { Specialist(kind) }\n                }\n                Revisions {\n                    Combine()\n                }\n            }\n            let r = try Detector.detect(cgImage: cg, config: InferenceConfig(), pipeline: pipeline)\n            let shipped = try Detector.detect(cgImage: cg, config: InferenceConfig())\n            #expect(r.stack.map(\\.name) == [\"screenshot\", \"camera\", \"capture\", \"art\", \"blur\", \"human\"] && r.revisions.map(\\.name) == [\"combiner\"])\n            #expect(r.p == shipped.revisions.revision(\"combiner\")?.p, \"the combiner reads the same members either way\")\n            let missing = Pipeline {\n                Stack {\n                    Camera()\n                    Capture()\n                }\n                Revisions {\n                    Combine()\n                }\n            }\n            #expect(throws: VeilGardeFailure.self, \"the combiner needs its evidence members\") { try Detector.detect(cgImage: cg, config: InferenceConfig(), pipeline: missing) }\n        }\n\n        @Test(\"DINOv2 reproduces the HF reference embeddings (cosine ≥ 0.999)\",\n              .enabled(if: FileManager.default.fileExists(atPath: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\").path)))\n        func dinoParity() throws {\n            let file = try SafetensorsFile(url: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\"))\n            let bases = Set(file.names.filter { $0.hasSuffix(\".pixels\") }.map { String($0.dropLast(7)) }).sorted()\n            #expect(!bases.isEmpty)\n            for base in bases {\n                let emb = try SemanticLens.embedding(pixels: try file.float32(\"\\(base).pixels\"))\n                let ref = try file.float32(\"\\(base).emb\")\n                var dot: Float = 0, na: Float = 0, nb: Float = 0\n                for i in 0..<emb.count { dot += emb[i] * ref[i]; na += emb[i] * emb[i]; nb += ref[i] * ref[i] }\n                let cos = dot / (na.squareRoot() * nb.squareRoot())\n                #expect(cos >= 0.999, \"\\(base): cosine \\(cos)\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/ShippedBundleTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,9],"target":"VeilGardeInferenceTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1406,"scopes":[["S","ShippedBundleTests",null,"",15,16,[16,26],37,null,-1,0,"a"],["f","defaults",[],"",17,18,[18,27],27,null,0,0,"a"],["f","combiner",[],"",29,30,[30,27],36,null,0,0,"a"]],"old":"","new":"//\n//  ShippedBundleTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The shipped bundle verifies, holds the camera head and the combiner trained on 2026-10-21\n//        and the six heads, the combiner pools members the stack holds, and the detector's defaults\n//        point into it at the camera member's operating point.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n@Suite(\"Shipped bundle\")\nstruct ShippedBundleTests {\n    @Test(\"the shipped bundle verifies and the defaults point into it\")\n    func defaults() throws {\n        let bundle = try ShippedBundle.verified()\n        #expect(bundle.manifest.artifacts.count == 8 && bundle.manifest.weights.count == 3)\n        #expect(bundle.manifest.artifact(.camera)?.sha256 == \"b142e661c609070a7838fb015ae47a8b9ccce2ab1d539c3dac29afadc48b8f9e\")\n        #expect(bundle.manifest.artifact(.combiner)?.file == \"stack_combiner.json\")\n        let config = InferenceConfig()\n        #expect(config.bundle.isShipped && config.decision == .camera && config.dinoVariant == .small && config.semanticResponsibility == .control)\n        #expect(config.bundle.url(.camera)?.lastPathComponent == \"camera.xgb.json\")\n        #expect(config.bundle.hashes.artifacts.count == 8 && config.bundle.provenance[\"camera_sha256\"] != nil)\n    }\n\n    @Test(\"the shipped combiner pools members the shipped pipeline holds\")\n    func combiner() throws {\n        let c = try #require(HeadRegistry.shared.combiner(in: .shipped))\n        let names = Pipeline.v1.stack.members.map(\\.name)\n        #expect(c.evidenceMembers == [\"art\", \"blur\", \"human\"] && c.evidenceMembers.allSatisfy(names.contains))\n        #expect(names.contains(\"camera\") && names.contains(\"screenshot\") && names.contains(\"capture\"))\n        #expect(Pipeline.v1.revisions.steps.map(\\.name) == [\"combiner\", \"frame-seam\", \"preview-tail\"])\n    }\n}\n"}]};
